targets.expr:
max by (name) (
  webtech_s3_exporter_up
    * on (instance, job) group_left (name)
      webtech_s3_exporter_info{name=~"$bucket"}
)

max by (name) (
  sum by (namespace, pod) (
    rate(container_cpu_usage_seconds_total{container!="", container!="POD"}[5m])
  ) * 1000
    * on (namespace, pod) group_left (name)
      webtech_s3_exporter_info{name=~"$bucket"}
)

max by (name) (
  sum by (namespace, pod) (
    container_memory_working_set_bytes{container!="", container!="POD"}
  )
    * on (namespace, pod) group_left (name)
      webtech_s3_exporter_info{name=~"$bucket"}
)

max by (name) (
  (
    sum by (namespace, pod) (rate(container_cpu_cfs_throttled_periods_total[5m]))
      / sum by (namespace, pod) (rate(container_cpu_cfs_periods_total[5m]))
  )
    * on (namespace, pod) group_left (name)
      webtech_s3_exporter_info{name=~"$bucket"}
)

max by (name) (
  webtech_s3_exporter_info{name=~"$bucket"}
    * on (instance, job, endpoint) group_left
      webtech_s3_endpoint_dns_duration_seconds
)
